css:
        * { margin: 0; padding: 0; box-sizing: border-box; user-select: none; -webkit-tap-highlight-color: transparent; }
        body { overflow: hidden; background: #0a0e14; font-family: 'Segoe UI', sans-serif; touch-action: none; }
        #game-container { width: 100vw; height: 100vh; display: block; position: relative; }

        #hud {
            position: fixed; top: 0; left: 0; right: 0; z-index: 100;
            display: flex; justify-content: space-between; padding: 6px 10px;
            background: linear-gradient(180deg, rgba(0,0,0,0.92) 0%, rgba(0,0,0,0) 100%);
            pointer-events: none; flex-wrap: wrap; gap: 4px;
        }
        #hud>* { pointer-events: auto; }

        .hud-left {
            display: flex; gap: 6px; align-items: center;
            background: rgba(0,0,0,0.7); padding: 4px 10px; border-radius: 8px;
            border: 1px solid rgba(255,215,0,0.25);
        }
        .hud-left .logo { color: #FFD700; font-size: 13px; font-weight: bold; letter-spacing: 1px; }
        .hud-left .stats { color: #aaa; font-size: 10px; margin-left: 6px; }
        .hud-left .stats span { color: #fff; font-weight: bold; }

        .hud-right {
            display: flex; gap: 4px; align-items: center;
            background: rgba(0,0,0,0.7); padding: 4px 8px; border-radius: 8px;
            border: 1px solid rgba(0,210,255,0.2);
        }
        .hud-right input {
            background: rgba(255,255,255,0.05); border: 1px solid #333;
            border-radius: 4px; padding: 3px 6px; color: #fff; font-size: 10px; width: 70px;
        }
        .hud-right button {
            background: #FFD700; color: #000; border: none; border-radius: 4px;
            padding: 2px 8px; font-size: 9px; font-weight: bold; cursor: pointer;
        }

        #score-display {
            background: rgba(0,0,0,0.7); padding: 4px 12px; border-radius: 8px;
            border: 1px solid rgba(0,210,255,0.2);
            font-size: 11px; color: #aaa;
            display: flex; align-items: center; gap: 10px;
        }
        #score-display span { color: #FFD700; font-weight: bold; }
        #user-email-display {
            font-size: 9px; color: #888; max-width: 120px;
            overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
        }

        #leaderboard {
            position: fixed; top: 48px; right: 8px; z-index: 100;
            background: rgba(0,0,0,0.88); padding: 8px 12px; border-radius: 10px;
            border: 1px solid rgba(255,215,0,0.3); min-width: 90px;
            pointer-events: none; max-height: 55vh; overflow-y: auto;
            backdrop-filter: blur(8px);
            box-shadow: 0 0 30px rgba(0,0,0,0.6);
        }
        #leaderboard .lb-title { color: #FFD700; font-size: 10px; font-weight: bold; text-align: center; margin-bottom: 4px; letter-spacing: 2px; }
        #leaderboard .lb-item {
            display: flex; justify-content: space-between; font-size: 9px;
            color: #ccc; padding: 3px 0; border-bottom: 1px solid rgba(255,255,255,0.06);
            gap: 8px;
        }
        #leaderboard .lb-item .rank { color: #FFD700; font-weight: bold; min-width: 22px; }
        #leaderboard .lb-item .lb-name { color: #fff; max-width: 60px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; }
        #leaderboard .lb-item .lb-score { color: #FFD700; font-weight: bold; min-width: 30px; text-align: right; }
        #leaderboard .lb-item.me { background: rgba(255,215,0,0.15); border-radius: 4px; padding: 3px 6px; margin: 0 -6px; }

        #controls {
            position: fixed; bottom: 10px; left: 0; right: 0; z-index: 100;
            display: flex; justify-content: space-between; padding: 0 10px; pointer-events: none;
        }
        #controls>* { pointer-events: auto; }

        .joystick-area { width: 90px; height: 90px; position: relative; }
        .joystick-base {
            width: 90px; height: 90px; border-radius: 50%;
            background: rgba(255,255,255,0.06); border: 2px solid rgba(255,255,255,0.12);
            position: absolute; bottom: 0; left: 0;
            display: flex; align-items: center; justify-content: center;
        }
        .joystick-knob {
            width: 34px; height: 34px; border-radius: 50%;
            background: rgba(255,215,0,0.25); border: 2px solid rgba(255,215,0,0.35);
            position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
            touch-action: none;
            box-shadow: 0 0 20px rgba(255,215,0,0.15);
        }

        .right-controls {
            display: flex; flex-direction: column; gap: 6px;
            align-items: flex-end; position: absolute; bottom: 0; right: 8px;
        }
        .rotate-buttons { display: flex; gap: 8px; }
        .rotate-btn {
            width: 54px; height: 42px; border-radius: 12px; border: none;
            font-size: 16px; font-weight: bold; touch-action: none; cursor: pointer;
            background: rgba(255,255,255,0.07); color: #fff;
            border: 1px solid rgba(255,255,255,0.12); transition: 0.1s;
        }
        .rotate-btn:active { transform: scale(0.9); background: rgba(255,215,0,0.2); }
        .rotate-btn .label { font-size: 7px; display: block; color: #888; }
        .rotate-btn .key { font-size: 18px; }
        .action-btn {
            width: 48px; height: 48px; border-radius: 50%; border: none;
            font-size: 16px; font-weight: bold; touch-action: none; cursor: pointer;
            box-shadow: 0 4px 15px rgba(0,0,0,0.6);
        }
        .action-btn:active { transform: scale(0.85); }
        .btn-jump { background: linear-gradient(135deg, #00d2ff, #3a7bd5); color: #fff; }

        #toast {
            position: fixed; bottom: 160px; left: 50%; transform: translateX(-50%);
            background: rgba(0,0,0,0.92); color: #FFD700; padding: 6px 18px;
            border-radius: 8px; border: 1px solid #FFD700; z-index: 9999;
            font-size: 12px; font-weight: bold; display: none; text-align: center;
            max-width: 90%; pointer-events: none;
        }
        #toast.show { display: block; animation: pop 0.3s ease; }
        @keyframes pop { from { transform: translateX(-50%) scale(0.8); opacity: 0; } to { transform: translateX(-50%) scale(1); opacity: 1; } }

        #loading {
            position: fixed; inset: 0; background: #0a0e14;
            display: flex; flex-direction: column; align-items: center; justify-content: center;
            z-index: 99999; color: #FFD700;
        }
        .spinner {
            width: 36px; height: 36px; border: 4px solid #333;
            border-top-color: #FFD700; border-radius: 50%;
            animation: spin 1s linear infinite; margin-bottom: 12px;
        }
        @keyframes spin { to { transform: rotate(360deg); } }
        #loading h2 { font-size: 18px; letter-spacing: 3px; }
        #loading p { color: #888; font-size: 12px; margin-top: 6px; }

        #minimap {
            position: fixed; bottom: 130px; left: 12px; z-index: 100;
            width: 85px; height: 85px; border-radius: 50%;
            background: rgba(0,0,0,0.8); border: 2px solid rgba(255,215,0,0.25);
            overflow: hidden; pointer-events: none;
            box-shadow: 0 0 40px rgba(0,0,0,0.6);
        }
        #minimap canvas { width: 100%; height: 100%; }

        #exit-confirm-overlay {
            position: fixed; inset: 0; background: rgba(0,0,0,0.85);
            z-index: 20000; display: none; align-items: center; justify-content: center;
            backdrop-filter: blur(10px);
        }
        .exit-box {
            background: #111; border: 2px solid #FFD700; border-radius: 25px;
            padding: 35px 40px; text-align: center; max-width: 360px; width: 90%;
            box-shadow: 0 0 60px rgba(255,215,0,0.15);
        }
        .exit-box h2 { color: #FFD700; font-size: 22px; margin-bottom: 8px; }
        .exit-box p { color: #aaa; font-size: 14px; margin-bottom: 20px; line-height: 1.5; }
        .exit-box .btn-row { display: flex; gap: 12px; }
        .exit-box .btn-row button {
            flex: 1; padding: 12px; border-radius: 12px; border: none;
            font-weight: bold; font-size: 14px; cursor: pointer; transition: 0.3s;
        }
        .exit-box .btn-yes { background: #FFD700; color: #000; }
        .exit-box .btn-yes:hover { transform: scale(1.04); box-shadow: 0 0 30px rgba(255,215,0,0.3); }
        .exit-box .btn-no { background: #333; color: #fff; border: 1px solid #555; }
        .exit-box .btn-no:hover { background: #444; }

        @media (max-width: 768px) {
            .joystick-area { width: 75px; height: 75px; }
            .joystick-base { width: 75px; height: 75px; }
            .joystick-knob { width: 28px; height: 28px; }
            .rotate-btn { width: 44px; height: 36px; font-size: 13px; }
            .action-btn { width: 40px; height: 40px; font-size: 13px; }
            #leaderboard { min-width: 75px; top: 44px; right: 5px; }
            #leaderboard .lb-item { font-size: 8px; }
            #leaderboard .lb-item .lb-name { max-width: 45px; }
            #minimap { width: 65px; height: 65px; bottom: 110px; }
            #score-display { font-size: 10px; }
        }
        @media (max-width: 480px) {
            .joystick-area { width: 62px; height: 62px; }
            .joystick-base { width: 62px; height: 62px; }
            .joystick-knob { width: 22px; height: 22px; }
            .rotate-btn { width: 38px; height: 30px; font-size: 11px; }
            .action-btn { width: 34px; height: 34px; font-size: 11px; }
            #minimap { width: 55px; height: 55px; bottom: 90px; }
            #leaderboard .lb-item .lb-name { max-width: 35px; }
            .exit-box { padding: 25px 20px; }
        }

