        // ============================================================
        // 1. FIREBASE CONFIG & AUTH
        // ============================================================
        const firebaseConfig = {
              apiKey: "AIzaSyC7kZON-2obr2-X_jC93a6oFg7FnxY6foc",
              authDomain: "mymarketbaazar.firebaseapp.com",
              databaseURL: "https://mymarketbaazar-default-rtdb.firebaseio.com",
              projectId: "mymarketbaazar",
        };
        firebase.initializeApp(firebaseConfig);
        const auth = firebase.auth();
        const db = firebase.database();

        // ============================================================
        // 2. GAME STATE
        // ============================================================
        const G = {
            scene: null, camera: null, renderer: null,
            players: {}, myPlayer: null, myUid: null,
            myName: 'Player', myEmail: 'unknown',
            coins: 0, score: 0,
            clock: new THREE.Clock(),
            moveSpeed: 16,
            chunkSize: 200,
            viewRadius: 2,          // optimized for heavy city
            chunks: new Map(),
            coinObjects: [],
            moveInput: { x: 0, z: 0 },
            isJumping: false, jumpForce: 0, gravity: -32,
            keys: {}, keyboardMode: false,
            cameraDistance: 18, cameraHeight: 14,
            currentCamPos: new THREE.Vector3(),
            rotatingLeft: false, rotatingRight: false,
            rotateSpeed: 0.1,
            cameraAngle: 0,
            frameCount: 0,
            updateInterval: null,
            minimapCtx: null,
            eventName: 'Event',
            collectedCoinIds: new Set(),
            dataLoaded: false
        };

        // ============================================================
        // 3. LOAD USER DATA (includes saved username)
        // ============================================================
        function loadUserData(callback) {
            if (!G.myUid) { callback(); return; }

            db.ref('users/' + G.myUid).once('value', snap => {
                const data = snap.val() || {};
                G.coins = data.coins || 0;
                G.score = data.cityScore || 0;
                if (data.gameName) G.myName = data.gameName;
                if (data.email) G.myEmail = data.email;
                document.getElementById('name-input').value = G.myName;

                db.ref('game_coins/' + G.myUid).once('value', coinSnap => {
                    const saved = coinSnap.val() || {};
                    Object.keys(saved).forEach(id => {
                        if (saved[id].collected) G.collectedCoinIds.add(id);
                    });
                    G.dataLoaded = true;
                    callback();
                });
            }).catch(() => { callback(); });
        }

        function saveUserData() {
            if (!G.myUid) return;
            db.ref('users/' + G.myUid).update({
                coins: G.coins,
                cityScore: G.score,
                gameName: G.myName,
                email: G.myEmail,
                lastGamePlayed: Date.now()
            }).catch(() => {});
        }

        function saveCoinCollected(id) {
            if (!G.myUid) return;
            db.ref('game_coins/' + G.myUid + '/' + id).set({ collected: true, time: Date.now() }).catch(() => {});
            saveUserData();
        }

        // ============================================================
        // 4. AUTH – ONLY REAL USERS (NO GUEST)
        // ============================================================
        function startGame() {
            auth.onAuthStateChanged(user => {
                if (user) {
                    G.myUid = user.uid;
                    G.myEmail = user.email || 'unknown';
                    G.myName = user.displayName || G.myEmail.split('@')[0].toUpperCase() || 'Player';
                    document.getElementById('name-input').value = G.myName;
                    document.getElementById('user-email-display').textContent = '👤 ' + G.myEmail;
                    loadUserData(() => initGame());
                } else {
                    // If URL has uid param (from market)
                    const urlParams = new URLSearchParams(window.location.search);
                    const uid = urlParams.get('uid');
                    const email = urlParams.get('email');
                    if (uid) {
                        G.myUid = uid;
                        G.myEmail = email || 'unknown';
                        G.myName = email ? email.split('@')[0].toUpperCase() : 'P' + uid.substring(0, 4);
                        document.getElementById('name-input').value = G.myName;
                        document.getElementById('user-email-display').textContent = '👤 ' + G.myEmail;
                        loadUserData(() => initGame());
                    } else {
                        alert('Please login first!');
                        window.location.href = 'index.html';
                    }
                }
            });
        }

        // ============================================================
        // 5. INIT GAME
        // ============================================================
        function initGame() {
            const container = document.getElementById('game-container');

            G.scene = new THREE.Scene();
            G.scene.background = new THREE.Color(0x87CEEB);
            G.scene.fog = new THREE.Fog(0x87CEEB, 120, 400);

            G.camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 600);
            G.camera.position.set(0, 24, 32);

            G.renderer = new THREE.WebGLRenderer({ antialias: true });
            G.renderer.setSize(window.innerWidth, window.innerHeight);
            G.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
            G.renderer.shadowMap.enabled = true;
            G.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
            container.appendChild(G.renderer.domElement);

            setupLights();
            createInitialWorld();
            createPlayer();
            setupMinimap();
            setupControls();

            animate();
            listenForPlayers();

            document.getElementById('loading').style.display = 'none';

            G.updateInterval = setInterval(updateMyPosition, 500);
            window.addEventListener('resize', onResize);

            // Day/Night cycle
            updateDayNightCycle();
            setInterval(updateDayNightCycle, 60000);

            showToast('🏘️ Welcome to Heavy City!');
            showToast('🔄 A/D to rotate camera');

            updateLeaderboard();
            setInterval(updateLeaderboard, 3000);

            updateUI();
            console.log('✅ Heavy City Started!', G.myUid);
        }

        // ============================================================
        // 6. LIGHTS
        // ============================================================
        function setupLights() {
            const ambient = new THREE.AmbientLight(0x4466aa, 0.5);
            G.scene.add(ambient);

            const hemi = new THREE.HemisphereLight(0x87CEEB, 0x3a2a1a, 0.6);
            G.scene.add(hemi);

            const sun = new THREE.DirectionalLight(0xffeedd, 1.0);
            sun.position.set(40, 70, 30);
            sun.castShadow = true;
            sun.shadow.mapSize.width = 1024;
            sun.shadow.mapSize.height = 1024;
            sun.shadow.camera.near = 0.5;
            sun.shadow.camera.far = 150;
            sun.shadow.camera.left = -60;
            sun.shadow.camera.right = 60;
            sun.shadow.camera.top = 60;
            sun.shadow.camera.bottom = -60;
            G.scene.add(sun);

            const moon = new THREE.DirectionalLight(0x4466ff, 0.1);
            moon.position.set(-40, 50, -30);
            G.scene.add(moon);

            G.ambientLight = ambient;
            G.hemisphereLight = hemi;
            G.sunLight = sun;
            G.moonLight = moon;
        }

        function updateDayNightCycle() {
            G.isNight = !G.isNight;
            if (G.isNight) {
                G.scene.background = new THREE.Color(0x0a0e1a);
                G.scene.fog = new THREE.Fog(0x0a0e1a, 80, 300);
                G.ambientLight.intensity = 0.15;
                G.hemisphereLight.intensity = 0.15;
                G.sunLight.intensity = 0.05;
                G.moonLight.intensity = 0.6;
                showToast('🌙 Night has fallen!');
            } else {
                G.scene.background = new THREE.Color(0x87CEEB);
                G.scene.fog = new THREE.Fog(0x87CEEB, 120, 400);
                G.ambientLight.intensity = 0.5;
                G.hemisphereLight.intensity = 0.6;
                G.sunLight.intensity = 1.0;
                G.moonLight.intensity = 0.1;
                showToast('☀️ Day has come!');
            }
        }

        // ============================================================
        // 7. HEAVY WORLD GENERATION (Zyada Trees, Huts, Coins)
        // ============================================================
        function getChunkKey(cx, cy) { return cx + ',' + cy; }

        function generateChunk(cx, cy) {
            const key = getChunkKey(cx, cy);
            if (G.chunks.has(key)) return;
            const size = G.chunkSize;
            const half = size / 2;
            const seed = cx * 100000 + cy * 7777;
            const rand = (n) => ((seed * 9301 + 49297) % 233280) / 233280 * n;

            const chunk = { cx, cy, elements: [], coins: [] };

            const isRoadH = (cy % 2 === 0);
            const isRoadV = (cx % 2 === 0);
            const roadW = 8;
            const baseX = cx * size;
            const baseZ = cy * size;

            // --- ROADS ---
            const roadMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.9 });
            if (isRoadH) {
                const road = new THREE.Mesh(new THREE.PlaneGeometry(size, roadW), roadMat);
                road.rotation.x = -Math.PI / 2;
                road.position.set(baseX + half, 0.05, baseZ + half);
                road.receiveShadow = true;
                G.scene.add(road);
                chunk.elements.push(road);
            }
            if (isRoadV) {
                const road = new THREE.Mesh(new THREE.PlaneGeometry(roadW, size), roadMat);
                road.rotation.x = -Math.PI / 2;
                road.position.set(baseX + half, 0.05, baseZ + half);
                road.receiveShadow = true;
                G.scene.add(road);
                chunk.elements.push(road);
            }

            // Road markings
            const markMat = new THREE.MeshStandardMaterial({ color: 0xcccccc, emissive: 0x444444, emissiveIntensity: 0.1 });
            if (isRoadH) {
                for (let i = -4; i <= 4; i += 2) {
                    const mark = new THREE.Mesh(new THREE.PlaneGeometry(0.3, 1.5), markMat);
                    mark.rotation.x = -Math.PI / 2;
                    mark.position.set(baseX + half + i * 10, 0.08, baseZ + half);
                    G.scene.add(mark);
                    chunk.elements.push(mark);
                }
            }
            if (isRoadV) {
                for (let i = -4; i <= 4; i += 2) {
                    const mark = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 0.3), markMat);
                    mark.rotation.x = -Math.PI / 2;
                    mark.position.set(baseX + half, 0.08, baseZ + half + i * 10);
                    G.scene.add(mark);
                    chunk.elements.push(mark);
                }
            }

            // --- HUTS / BUILDINGS (ZYADA) ---
            const numBuildings = 8 + Math.floor(rand(6));  // 8-14 buildings per chunk
            for (let i = 0; i < numBuildings; i++) {
                let bx = 18 + rand(size - 36);
                let bz = 18 + rand(size - 36);
                if (isRoadH && bz > half - roadW/2 - 2 && bz < half + roadW/2 + 2) continue;
                if (isRoadV && bx > half - roadW/2 - 2 && bx < half + roadW/2 + 2) continue;

                const w = 2.5 + rand(6);
                const d = 2.5 + rand(6);
                const h = 2.5 + rand(5);
                const wallColor = new THREE.Color().setHSL(0.08 + rand(0.12), 0.3 + rand(0.4), 0.4 + rand(0.4));
                const roofColor = new THREE.Color().setHSL(0.05 + rand(0.08), 0.6, 0.25 + rand(0.35));

                const group = new THREE.Group();
                const bodyMat = new THREE.MeshStandardMaterial({ color: wallColor, roughness: 0.7 });
                const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), bodyMat);
                body.position.y = h / 2;
                body.castShadow = true;
                body.receiveShadow = true;
                group.add(body);

                const roofMat = new THREE.MeshStandardMaterial({ color: roofColor, roughness: 0.9 });
                const roof = new THREE.Mesh(new THREE.ConeGeometry(Math.max(w, d) * 0.75, 1.8, 4), roofMat);
                roof.position.y = h + 0.1;
                roof.rotation.y = Math.PI / 4;
                roof.castShadow = true;
                group.add(roof);

                // Windows
                const winMat = new THREE.MeshStandardMaterial({ color: 0x88ccff, emissive: 0x4488ff, emissiveIntensity: 0.05 });
                for (let wi = 0; wi < 3; wi++) {
                    const win = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.35, 0.05), winMat);
                    win.position.set((wi - 1) * 0.7, 0.7 + Math.random() * 0.6, d/2 + 0.02);
                    group.add(win);
                    const win2 = new THREE.Mesh(new THREE.BoxGeometry(0.25, 0.35, 0.05), winMat);
                    win2.position.set((wi - 1) * 0.7, 0.7 + Math.random() * 0.6, -d/2 - 0.02);
                    group.add(win2);
                }

                group.position.set(baseX + bx, 0, baseZ + bz);
                G.scene.add(group);
                chunk.elements.push(group);
            }

            // --- TREES (ZYADA) ---
            const numTrees = 10 + Math.floor(rand(8));  // 10-18 trees
            const trunkMat = new THREE.MeshStandardMaterial({ color: 0x3a2a1a, roughness: 0.9 });
            const leafMat = new THREE.MeshStandardMaterial({ color: 0x2a7a2a, roughness: 0.8 });
            for (let i = 0; i < numTrees; i++) {
                let tx = 12 + rand(size - 24);
                let tz = 12 + rand(size - 24);
                if (isRoadH && tz > half - roadW/2 - 2 && tz < half + roadW/2 + 2) continue;
                if (isRoadV && tx > half - roadW/2 - 2 && tx < half + roadW/2 + 2) continue;

                const h = 2 + rand(3.5);
                const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.2, h, 5), trunkMat);
                trunk.position.set(baseX + tx, h/2, baseZ + tz);
                trunk.castShadow = true;
                G.scene.add(trunk);
                chunk.elements.push(trunk);

                // Multiple leaf layers for fullness
                const leafMat2 = new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(0.25 + rand(0.08), 0.6, 0.3 + rand(0.2)), roughness: 0.8 });
                for (let l = 0; l < 3; l++) {
                    const leaf = new THREE.Mesh(new THREE.SphereGeometry(0.6 + rand(1.0), 5, 5), l === 0 ? leafMat : leafMat2);
                    leaf.position.set(baseX + tx + (l-1)*0.4, h + 0.2 + l*0.25, baseZ + tz + (l-1)*0.4);
                    leaf.castShadow = true;
                    G.scene.add(leaf);
                    chunk.elements.push(leaf);
                }
            }

            // --- FLOWERS (ZYADA) ---
            const numFlowers = 15 + Math.floor(rand(10));
            for (let i = 0; i < numFlowers; i++) {
                let fx = 8 + rand(size - 16);
                let fz = 8 + rand(size - 16);
                if (isRoadH && fz > half - roadW/2 - 2 && fz < half + roadW/2 + 2) continue;
                if (isRoadV && fx > half - roadW/2 - 2 && fx < half + roadW/2 + 2) continue;
                const color = new THREE.Color().setHSL(0.9 + rand(0.2), 0.8, 0.6);
                const mat = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.1 });
                const flower = new THREE.Mesh(new THREE.SphereGeometry(0.12, 4, 4), mat);
                flower.position.set(baseX + fx, 0.08, baseZ + fz);
                G.scene.add(flower);
                chunk.elements.push(flower);
            }

            // --- COINS (ZYADA, 10 POINTS EACH) ---
            const numCoins = 4 + (rand(3) > 0.5 ? 3 : 0);  // 4-7 coins per chunk
            const coinMat = new THREE.MeshStandardMaterial({
                color: 0xFFD700, emissive: 0xFFD700, emissiveIntensity: 0.5,
                metalness: 0.9, roughness: 0.1, side: THREE.DoubleSide
            });
            for (let i = 0; i < numCoins; i++) {
                let cx2, cz2;
                let valid = false;
                let attempts = 0;
                while (!valid && attempts < 30) {
                    if (Math.random() > 0.5) {
                        if (isRoadH) {
                            cx2 = 20 + rand(size - 40);
                            cz2 = half + (rand(roadW - 2) - (roadW - 2) / 2);
                        } else if (isRoadV) {
                            cx2 = half + (rand(roadW - 2) - (roadW - 2) / 2);
                            cz2 = 20 + rand(size - 40);
                        } else {
                            cx2 = 20 + rand(size - 40);
                            cz2 = 20 + rand(size - 40);
                        }
                    } else {
                        cx2 = 20 + rand(size - 40);
                        cz2 = 20 + rand(size - 40);
                        if (isRoadH && cz2 > half - roadW/2 - 2 && cz2 < half + roadW/2 + 2) continue;
                        if (isRoadV && cx2 > half - roadW/2 - 2 && cx2 < half + roadW/2 + 2) continue;
                    }
                    valid = true;
                    attempts++;
                }
                const coinId = `${baseX + cx2}_${baseZ + cz2}`;
                if (G.collectedCoinIds.has(coinId)) continue;

                // STAR SHAPE
                function createStar(inner, outer, points) {
                    const shape = new THREE.Shape();
                    const step = Math.PI / points;
                    for (let j = 0; j < points * 2; j++) {
                        const r = j % 2 === 0 ? outer : inner;
                        const a = j * step - Math.PI / 2;
                        if (j === 0) shape.moveTo(Math.cos(a) * r, Math.sin(a) * r);
                        else shape.lineTo(Math.cos(a) * r, Math.sin(a) * r);
                    }
                    shape.closePath();
                    return shape;
                }
                const starShape = createStar(0.1, 0.35, 5);
                const starGeom = new THREE.ShapeGeometry(starShape);
                const coin = new THREE.Mesh(starGeom, coinMat);
                coin.position.set(baseX + cx2, 0.4, baseZ + cz2);
                coin.rotation.x = -Math.PI / 2;
                coin.rotation.z = Math.PI / 2;
                coin.castShadow = true;
                G.scene.add(coin);

                // Glow ring
                const glowMat = new THREE.MeshBasicMaterial({
                    color: 0xFFD700,
                    transparent: true,
                    opacity: 0.2,
                    side: THREE.DoubleSide
                });
                const glow = new THREE.Mesh(new THREE.RingGeometry(0.4, 0.7, 16), glowMat);
                glow.position.set(baseX + cx2, 0.38, baseZ + cz2);
                glow.rotation.x = -Math.PI / 2;
                G.scene.add(glow);

                const coinData = {
                    mesh: coin,
                    glow: glow,
                    id: coinId,
                    x: baseX + cx2,
                    z: baseZ + cz2,
                    collected: false,
                    value: 1
                };
                G.coinObjects.push(coinData);
                chunk.coins.push(coinData);
                chunk.elements.push(coin);
                chunk.elements.push(glow);
            }

            G.chunks.set(key, chunk);
        }

        function createInitialWorld() {
            const groundGeo = new THREE.PlaneGeometry(4000, 4000);
            const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a6a3a, roughness: 0.95 });
            const ground = new THREE.Mesh(groundGeo, groundMat);
            ground.rotation.x = -Math.PI / 2;
            ground.position.y = -0.5;
            ground.receiveShadow = true;
            G.scene.add(ground);

            for (let dx = -G.viewRadius; dx <= G.viewRadius; dx++) {
                for (let dz = -G.viewRadius; dz <= G.viewRadius; dz++) {
                    generateChunk(dx, dz);
                }
            }
        }

        function updateChunks() {
            if (!G.myPlayer) return;
            const pos = G.myPlayer.position;
            const cx = Math.floor(pos.x / G.chunkSize);
            const cz = Math.floor(pos.z / G.chunkSize);

            for (let dx = -G.viewRadius; dx <= G.viewRadius; dx++) {
                for (let dz = -G.viewRadius; dz <= G.viewRadius; dz++) {
                    generateChunk(cx + dx, cz + dz);
                }
            }
        }

        // ============================================================
        // 8. COIN PICKUP (10 POINTS PER COIN)
        // ============================================================
        function checkCoinPickup() {
            if (!G.myPlayer) return;
            const pos = G.myPlayer.position;
            const toRemove = [];
            G.coinObjects.forEach((coin, index) => {
                if (coin.collected) return;
                const dx = pos.x - coin.x;
                const dz = pos.z - coin.z;
                if (dx * dx + dz * dz < 1.8 * 1.8) {
                    coin.collected = true;
                    G.scene.remove(coin.mesh);
                    if (coin.glow) G.scene.remove(coin.glow);
                    G.coins += coin.value;
                    G.score += coin.value * 10;   // 10 points per coin
                    G.collectedCoinIds.add(coin.id);
                    saveCoinCollected(coin.id);
                    updateUI();
                    showToast('🪙 +10 points!');
                    updateMyPosition();
                    toRemove.push(index);
                }
            });
            if (toRemove.length > 0) {
                G.coinObjects = G.coinObjects.filter((c, i) => !toRemove.includes(i));
            }
        }

