        function createNameLabel(obj, name, isMe) {
            const old = obj.getObjectByName('label');
            if (old) obj.remove(old);

            const canvas = document.createElement('canvas');
            canvas.width = 256;
            canvas.height = 48;
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = 'rgba(0,0,0,0.7)';
            ctx.roundRect(0, 0, 256, 48, 10);
            ctx.fill();
            ctx.strokeStyle = isMe ? '#00d2ff' : '#FFD700';
            ctx.lineWidth = 2;
            ctx.roundRect(0, 0, 256, 48, 10);
            ctx.stroke();
            ctx.font = 'bold 18px Arial';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillStyle = isMe ? '#00d2ff' : '#FFD700';
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 8;
            ctx.fillText(name || 'Player', 128, 26);

            const texture = new THREE.CanvasTexture(canvas);
            const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false }));
            sprite.name = 'label';
            sprite.scale.set(4, 0.8, 1);
            sprite.position.y = 2.5;
            obj.add(sprite);
        }

        // ============================================================
        // 10. REMOTE PLAYERS
        // ============================================================
        function listenForPlayers() {
            db.ref('game_players').on('value', snap => {
                const players = snap.val() || {};
                const current = {};
                Object.keys(players).forEach(uid => {
                    if (uid === G.myUid) return;
                    const data = players[uid];
                    if (!data) return;
                    if (Date.now() - (data.lastSeen || 0) > 8000) {
                        if (G.players[uid] && G.players[uid].mesh) {
                            G.scene.remove(G.players[uid].mesh);
                            delete G.players[uid];
                        }
                        return;
                    }
                    current[uid] = data;
                    if (!G.players[uid]) createRemotePlayer(uid, data);
                    else updateRemotePlayer(uid, data);
                });
                Object.keys(G.players).forEach(uid => {
                    if (!current[uid] && uid !== G.myUid) {
                        if (G.players[uid].mesh) G.scene.remove(G.players[uid].mesh);
                        delete G.players[uid];
                    }
                });
                document.getElementById('player-count').textContent = Object.keys(current).length + 1;
            });
        }

        function createRemotePlayer(uid, data) {
            const group = new THREE.Group();
            const bodyMat = new THREE.MeshStandardMaterial({ color: 0xff4466, emissive: 0x660022, emissiveIntensity: 0.2 });
            const body = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.9, 0.4), bodyMat);
            body.position.y = 0.45;
            body.castShadow = true;
            group.add(body);

            const headMat = new THREE.MeshStandardMaterial({ color: 0xffccaa });
            const head = new THREE.Mesh(new THREE.SphereGeometry(0.3, 8, 8), headMat);
            head.position.y = 1.15;
            head.castShadow = true;
            group.add(head);

            if (data.position) group.position.set(data.position[0], 0, data.position[2]);
            G.scene.add(group);
            G.players[uid] = {
                mesh: group,
                name: data.name || 'Player',
                data: data,
                email: data.email || 'unknown'
            };
            createNameLabel(group, data.name || 'Player', false);
        }

        function updateRemotePlayer(uid, data) {
            const p = G.players[uid];
            if (!p || !p.mesh) return;
            if (data.position) {
                const target = new THREE.Vector3(data.position[0], 0, data.position[2]);
                p.mesh.position.lerp(target, 0.2);
            }
            if (data.rotation !== undefined) p.mesh.rotation.y = data.rotation;
            if (data.name && p.name !== data.name) {
                p.name = data.name;
                createNameLabel(p.mesh, data.name, false);
            }
            p.data = data;
            p.email = data.email || 'unknown';
        }

