        // ============================================================
        // 13. CONTROLS (FIXED – sahi direction)
        // ============================================================
        function setupControls() {
            const area = document.getElementById('joystick-area');
            const knob = document.getElementById('joystick-knob');
            let dragging = false, touchId = null, center = { x: 0, y: 0 }, radius = 30;

            const start = (cx, cy) => {
                const rect = area.getBoundingClientRect();
                center.x = rect.left + rect.width / 2;
                center.y = rect.top + rect.height / 2;
                dragging = true;
                move(cx, cy);
            };

            const move = (cx, cy) => {
                if (!dragging) return;
                const dx = cx - center.x, dy = cy - center.y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                let cx2 = dx, cy2 = dy;
                if (dist > radius) { cx2 = (dx / dist) * radius; cy2 = (dy / dist) * radius; }
                knob.style.transform = `translate(calc(-50% + ${cx2}px), calc(-50% + ${cy2}px))`;
                const mx = cx2 / radius, mz = cy2 / radius;
                if (Math.abs(mx) > 0.05 || Math.abs(mz) > 0.05) {
                    // FIXED: -mx for x, +mz for z
                    G.moveInput = { x: Math.max(-1, Math.min(1, -mx)), z: Math.max(-1, Math.min(1, mz)) };
                } else {
                    G.moveInput = { x: 0, z: 0 };
                }
            };

            const end = () => {
                dragging = false;
                knob.style.transform = 'translate(-50%, -50%)';
                G.moveInput = { x: 0, z: 0 };
            };

            area.addEventListener('touchstart', e => {
                e.preventDefault();
                const t = e.changedTouches[0];
                touchId = t.identifier;
                start(t.clientX, t.clientY);
            });
            document.addEventListener('touchmove', e => {
                if (!dragging) return;
                for (const t of e.changedTouches) {
                    if (touchId === t.identifier) { e.preventDefault(); move(t.clientX, t.clientY); }
                }
            }, { passive: false });
            document.addEventListener('touchend', e => {
                for (const t of e.changedTouches) {
                    if (touchId === t.identifier) { end(); touchId = null; }
                }
            });

            let mouseDown = false;
            area.addEventListener('mousedown', e => { mouseDown = true; start(e.clientX, e.clientY); });
            document.addEventListener('mousemove', e => { if (mouseDown) move(e.clientX, e.clientY); });
            document.addEventListener('mouseup', () => { if (mouseDown) { mouseDown = false; end(); } });

            // Rotation buttons – FIXED direction
            document.getElementById('btn-left').addEventListener('touchstart', e => { e.preventDefault(); G.rotatingLeft = true; });
            document.getElementById('btn-left').addEventListener('touchend', e => { e.preventDefault(); G.rotatingLeft = false; });
            document.getElementById('btn-left').addEventListener('mousedown', e => { e.preventDefault(); G.rotatingLeft = true; });
            document.getElementById('btn-left').addEventListener('mouseup', e => { e.preventDefault(); G.rotatingLeft = false; });
            document.getElementById('btn-left').addEventListener('mouseleave', e => { G.rotatingLeft = false; });

            document.getElementById('btn-right').addEventListener('touchstart', e => { e.preventDefault(); G.rotatingRight = true; });
            document.getElementById('btn-right').addEventListener('touchend', e => { e.preventDefault(); G.rotatingRight = false; });
            document.getElementById('btn-right').addEventListener('mousedown', e => { e.preventDefault(); G.rotatingRight = true; });
            document.getElementById('btn-right').addEventListener('mouseup', e => { e.preventDefault(); G.rotatingRight = false; });
            document.getElementById('btn-right').addEventListener('mouseleave', e => { G.rotatingRight = false; });

            document.getElementById('btn-jump').addEventListener('touchstart', e => { e.preventDefault(); jump(); });
            document.getElementById('btn-jump').addEventListener('mousedown', e => { e.preventDefault(); jump(); });

            document.addEventListener('keydown', e => {
                const k = e.key.toLowerCase();
                G.keys[k] = true;
                G.keyboardMode = true;
                if (k === ' ' || k === 'space') { e.preventDefault(); jump(); }
                if (k === 'enter') { e.preventDefault(); changeName(); }
                if (k === 'a') { G.rotatingLeft = true; }
                if (k === 'd') { G.rotatingRight = true; }
                updateKeyboardMovement();
            });
            document.addEventListener('keyup', e => {
                const k = e.key.toLowerCase();
                G.keys[k] = false;
                if (k === 'a') { G.rotatingLeft = false; }
                if (k === 'd') { G.rotatingRight = false; }
                updateKeyboardMovement();
            });

            document.addEventListener('keydown', e => {
                if (e.key === 'Escape') showExitConfirm();
            });
        }

        function updateKeyboardMovement() {
            if (!G.keyboardMode) return;
            let x = 0, z = 0;
            if (G.keys.w) z = -1;
            if (G.keys.s) z = 1;
            if (G.keys.a && !G.rotatingLeft) x = -1;
            if (G.keys.d && !G.rotatingRight) x = 1;
            const len = Math.sqrt(x * x + z * z);
            if (len > 0) { x /= len; z /= len; }
            G.moveInput = { x, z };
        }

        function jump() {
            if (!G.isJumping && G.myPlayer) {
                G.isJumping = true;
                G.jumpForce = 13;
