        // ============================================================
        // 15. MINIMAP
        // ============================================================
        function setupMinimap() {
            const canvas = document.getElementById('minimap-canvas');
            canvas.width = 85;
            canvas.height = 85;
            G.minimapCtx = canvas.getContext('2d');
        }

        function updateMinimap() {
            if (!G.minimapCtx) return;
            const ctx = G.minimapCtx;
            ctx.clearRect(0, 0, 85, 85);
            ctx.fillStyle = 'rgba(20,45,20,0.85)';
            ctx.beginPath();
            ctx.arc(42.5, 42.5, 42.5, 0, Math.PI * 2);
            ctx.fill();

            const myPos = G.myPlayer ? G.myPlayer.position : new THREE.Vector3(0, 0, 0);
            const half = 42.5;
            const scale = 0.6;

            Object.keys(G.players).forEach(uid => {
                const p = G.players[uid];
                if (!p || !p.mesh) return;
                const pos = p.mesh.position;
                const dx = (pos.x - myPos.x) * scale + half;
                const dz = (pos.z - myPos.z) * scale + half;
                if (dx > 2 && dx < 83 && dz > 2 && dz < 83) {
                    ctx.fillStyle = '#ff4466';
                    ctx.shadowColor = '#ff4466';
                    ctx.shadowBlur = 6;
                    ctx.beginPath();
                    ctx.arc(dx, dz, 3, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.shadowBlur = 0;
                }
            });

            ctx.shadowColor = '#FFD700';
            ctx.shadowBlur = 10;
            ctx.fillStyle = '#FFD700';
            ctx.beginPath();
            ctx.arc(half, half, 5, 0, Math.PI * 2);
            ctx.fill();
            ctx.shadowBlur = 0;

            G.coinObjects.forEach(coin => {
                if (coin.collected) return;
                const dx = (coin.x - myPos.x) * scale + half;
                const dz = (coin.z - myPos.z) * scale + half;
                if (dx > 0 && dx < 85 && dz > 0 && dz < 85) {
                    ctx.fillStyle = '#FFD700';
                    ctx.shadowColor = '#FFD700';
                    ctx.shadowBlur = 4;
                    ctx.beginPath();
                    ctx.arc(dx, dz, 2, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.shadowBlur = 0;
                }
            });

            ctx.strokeStyle = 'rgba(255,215,0,0.3)';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.arc(42.5, 42.5, 41.5, 0, Math.PI * 2);
            ctx.stroke();
        }

