        // ============================================================
        // 19. ANIMATION LOOP
        // ============================================================
        function animate() {
            requestAnimationFrame(animate);
            const delta = Math.min(G.clock.getDelta(), 0.05);

            if (G.myPlayer && !G.isGameEnded) {
                let x = G.moveInput.x || 0, z = G.moveInput.z || 0;
                if (x !== 0 || z !== 0) {
                    const camDir = new THREE.Vector3();
                    G.camera.getWorldDirection(camDir);
                    camDir.y = 0;
                    camDir.normalize();
                    const camRight = new THREE.Vector3();
                    camRight.crossVectors(camDir, new THREE.Vector3(0, 1, 0));
                    camRight.normalize();
                    const moveVec = new THREE.Vector3()
                        .addScaledVector(camRight, x)
                        .addScaledVector(camDir, -z);
                    if (moveVec.length() > 0) {
                        moveVec.normalize();
                        G.myPlayer.rotation.y = Math.atan2(moveVec.x, moveVec.z);
                        G.myPlayer.position.x += moveVec.x * G.moveSpeed * delta;
                        G.myPlayer.position.z += moveVec.z * G.moveSpeed * delta;
                    }
                }

                if (G.isJumping) {
                    G.myPlayer.position.y += G.jumpForce * delta;
                    G.jumpForce += G.gravity * delta;
                    if (G.myPlayer.position.y <= 0) {
                        G.myPlayer.position.y = 0;
                        G.isJumping = false;
                        G.jumpForce = 0;
                    }
                }

                updateChunks();
                checkCoinPickup();
                if (G.frameCount % 10 === 0) updateUI();
            }

            if (G.myPlayer) {
                const pos = G.myPlayer.position;
                if (G.rotatingLeft) G.cameraAngle += G.rotateSpeed * delta * 15;   // FIXED: + for left
                if (G.rotatingRight) G.cameraAngle -= G.rotateSpeed * delta * 15;  // FIXED: - for right
                const totalRot = G.cameraAngle;
                const target = new THREE.Vector3(
                    pos.x - Math.sin(totalRot) * G.cameraDistance,
                    pos.y + G.cameraHeight,
                    pos.z - Math.cos(totalRot) * G.cameraDistance
                );
                if (!G.currentCamPos.length()) G.currentCamPos.copy(target);
                G.currentCamPos.lerp(target, 0.15);
                G.camera.position.copy(G.currentCamPos);
